import forge.ai.*;
import forge.ai.bridge.*;
import forge.deck.Deck;
import forge.game.*;
import forge.game.card.*;
import forge.game.player.*;
import forge.game.phase.*;
import forge.game.zone.*;
import com.google.gson.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

/** Live stack targeting, actual blue payment and native counter/Bird resolution. */
public class SwanSongReplayRegression extends AITest {
 public static void main(String[] args)throws Exception {
  String mode=args[0];Path root=Path.of(args[1]);Files.createDirectories(root);System.setProperty("forge.audit.directory",root.resolve("audit").toString());SwanSongReplayRegression test=new SwanSongReplayRegression();test.initializeModel();test.initAndCreateGame();List<RegisteredPlayer> seats=new ArrayList<>();for(int i=0;i<4;i++)seats.add(new RegisteredPlayer(new Deck()).setPlayer(new LobbyPlayerAi("seat"+i,null)));GameRules rules=new GameRules(GameType.Commander);Game game=new Game(seats,rules,new Match(rules,seats,"Counter replay"));Player p=game.getPlayers().get(0),opponent=game.getPlayers().get(1);for(Player x:game.getPlayers())test.fillLibrary(x,10);game.setAge(GameStage.Play);game.getPhaseHandler().devModeSet(PhaseType.MAIN1,opponent,false);game.getPhaseHandler().setPriority(p);
  Card targetCard=test.addCardToZone(mode.equals("artifact")?"Sol Ring":"Rampant Growth",opponent,ZoneType.Hand);var target=targetCard.getFirstSpellAbility();target.setActivatingPlayer(opponent);targetCard=game.getAction().moveToStack(targetCard,target);target=targetCard.getFirstSpellAbility();target.setActivatingPlayer(opponent);game.getStack().add(target);Card card=test.addCardToZone("Swan Song",p,ZoneType.Hand),island=test.addCardToZone("Island",p,ZoneType.Battlefield);var spell=card.getFirstSpellAbility();var mana=island.getManaAbilities().get(0);if(mode.equals("tapped"))island.setTapped(true);
  JsonObject row=new JsonObject();row.addProperty("kind","decision");row.addProperty("index",0);row.addProperty("actor_id",p.getId());row.addProperty("hook","forge/ai/bridge/PlayerControllerBridge.chooseSpellAbilityToPlay()Ljava/util/List;");row.addProperty("decision_type","swan_song_spell");row.addProperty("source_card_id",card.getId());row.addProperty("source_name","Swan Song");row.addProperty("original_ability_id",spell.getId());row.addProperty("target_spell_card_id",mode.equals("missing")?99999:targetCard.getId());row.addProperty("target_spell_name",targetCard.getName());JsonObject params=new JsonObject();spell.getMapParams().forEach(params::addProperty);row.add("ability_parameters",params);JsonObject context=new JsonObject();context.addProperty("turn",game.getPhaseHandler().getTurn());context.addProperty("phase","MAIN1");context.addProperty("priority_player_id",p.getId());context.addProperty("turn_player_id",opponent.getId());row.add("context",context);
  JsonObject payment=new JsonObject();payment.addProperty("kind","decision");payment.addProperty("index",1);payment.addProperty("actor_id",p.getId());payment.addProperty("hook","forge/game/player/PlayerController.payManaCost(Lforge/game/cost/CostPartMana;Lforge/game/spellability/SpellAbility;Ljava/lang/String;Lforge/game/mana/ManaConversionMatrix;Z)Z");payment.addProperty("decision_type","basic_land_mana");payment.addProperty("component","{U}");payment.addProperty("source_ability",card.getId()+":"+spell.getId());payment.addProperty("ability_api","Counter");payment.add("ability_parameters",params);payment.addProperty("target_spell_card_id",targetCard.getId());payment.addProperty("target_spell_name",targetCard.getName());JsonArray operations=new JsonArray();JsonObject activation=new JsonObject();activation.addProperty("op","activate_basic");activation.addProperty("card_id",island.getId());activation.addProperty("card_name","Island");JsonObject production=new JsonObject();mana.getMapParams().forEach(production::addProperty);activation.add("parameters",production);operations.add(activation);JsonObject spend=new JsonObject();spend.addProperty("op","spend");JsonObject unit=new JsonObject();unit.addProperty("source_card_id",island.getId());unit.addProperty("color","U");unit.addProperty("snow",false);unit.addProperty("restricted",false);spend.add("mana",unit);operations.add(spend);payment.add("operations",operations);
  Path tape=root.resolve("decisions.jsonl");Files.writeString(tape,row+"\n"+payment+"\n{\"kind\":\"decision_tape_complete\",\"decisions\":2}\n",StandardOpenOption.CREATE_NEW);System.setProperty("forge.decision.replayTape",tape.toString());System.setProperty("forge.decision.replaySha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(tape))));System.setProperty("forge.decision.replayDiagnostics",root.resolve("diagnostics").toString());game.getPhaseHandler().setPriority(p);DurableEvidence.begin("swan-song-fixture");EngineEvidence.begin(game);
  try{var selected=p.getController().chooseSpellAbilityToPlay();if(mode.equals("missing")||mode.equals("artifact"))throw new AssertionError("Illegal target accepted");if(selected.size()!=1||selected.get(0)!=spell||spell.getTargets().getFirstTargetedSpell()!=target||!card.isInZone(ZoneType.Hand)||game.getStack().size()!=1)throw new AssertionError("Choice copied cast/counter outcome");if(!ComputerUtil.handlePlayingSpellAbility(p,spell,null))throw new AssertionError("Actual counter cast failed");if(mode.equals("tapped"))throw new AssertionError("Tapped source accepted");if(!island.isTapped()||!p.getManaPool().isEmpty()||game.getStack().peekAbility().getPayingMana().size()!=1)throw new AssertionError("Actual blue payment missing");game.getStack().resolveStack();int counterId=card.getId(),targetId=targetCard.getId();if(p.getCardsIn(ZoneType.Graveyard).stream().noneMatch(c->c.getId()==counterId)||opponent.getCardsIn(ZoneType.Graveyard).stream().noneMatch(c->c.getId()==targetId)||!game.getStack().isEmpty())throw new AssertionError("Native counter/zone result wrong");var birds=opponent.getCardsIn(ZoneType.Battlefield).stream().filter(c->c.isToken()&&c.getName().equals("Bird Token")).toList();if(birds.size()!=1||birds.get(0).getOwner()!=opponent||birds.get(0).getController()!=opponent||birds.get(0).getNetPower()!=2||birds.get(0).getNetToughness()!=2)throw new AssertionError("Bird recipient/ownership/PT wrong");for(Player other:game.getPlayers())if(other!=opponent&&other.getCardsIn(ZoneType.Battlefield).stream().anyMatch(Card::isToken))throw new AssertionError("Bird given to wrong player");DecisionReplay.finish();EngineEvidence.finish();JsonObject result=new JsonObject();result.addProperty("seed",104);result.addProperty("status","completed");DurableEvidence.finish(root.resolve("results"),104,"fixture\nDragonMind Result: "+result+"\n",result);System.out.println("PASS four-player Swan Song actual live target/blue payment/counter; original spell controller owns2/2 Bird");}
  catch(IllegalStateException error){String expected=mode.equals("tapped")?"Unavailable basic mana":"Illegal or missing recorded counter target";if(mode.equals("valid")||!error.getMessage().contains(expected))throw error;if(!p.getManaPool().isEmpty()||(!mode.equals("tapped")&&(!spell.getTargets().isEmpty()||!card.isInZone(ZoneType.Hand))))throw new AssertionError("Invalid choice mutated source/target/pool");System.out.println("PASS four-player Swan Song invalid "+mode+" rejected");}System.exit(0);
 }
}
